@Composable
fun LibraryScreen(viewModel:LibraryViewModel,languagePair:LanguagePair=LanguagePair(),onBack:()->Unit={},onOpen:(UUID)->Unit={},onAddWord:()->Unit={},onBulkImport:()->Unit={}){
 val state by viewModel.state.collectAsState(); val tokens=LocalFlashLearnThemeTokens.current; var duplicateMessage by remember{mutableStateOf<String?>(null)}
 LaunchedEffect(languagePair){viewModel.setLanguagePair(languagePair)}; LaunchedEffect(Unit){viewModel.refresh()}
 Column(Modifier.fillMaxSize().background(tokens.background).padding(horizontal=tokens.screenPadding,vertical=tokens.screenVerticalPadding)){
  Box(Modifier.fillMaxWidth().height(tokens.libraryHeaderHeight)){IconButton(onClick=onBack,modifier=Modifier.align(Alignment.CenterEnd)){Icon(tokens.icons.back,"بازگشت",tint=tokens.primary)};Text("واژگان",Modifier.align(Alignment.Center),color=tokens.primary,style=MaterialTheme.typography.headlineMedium.copy(fontWeight=FontWeight.Bold))}
  OutlinedTextField(value=state.query,onValueChange=viewModel::onQueryChange,modifier=Modifier.fillMaxWidth().height(tokens.librarySearchHeight),placeholder={Text("جستجو در واژگان...",color=tokens.onSurfaceVariant,textAlign=TextAlign.End,modifier=Modifier.fillMaxWidth())},trailingIcon={Row(verticalAlignment=Alignment.CenterVertically){Icon(tokens.icons.search,"جستجو",tint=tokens.primary);IconButton(onClick=viewModel::refresh,enabled=!state.isLoading){Icon(tokens.icons.refresh,"رفرش واژگان",tint=tokens.secondary)}}},singleLine=true,shape=RoundedCornerShape(tokens.librarySearchCorner),colors=OutlinedTextFieldDefaults.colors(focusedBorderColor=tokens.primary,unfocusedBorderColor=tokens.outlineColor,focusedContainerColor=tokens.surface,unfocusedContainerColor=tokens.surface))
  Spacer(Modifier.height(tokens.sectionGap));Row(Modifier.fillMaxWidth(),horizontalArrangement=Arrangement.spacedBy(tokens.itemGap)){LibraryStatCard("جدید",state.newCount,tokens.warning,tokens.warning.copy(alpha=.10f),tokens.icons.add,Modifier.weight(1f));LibraryStatCard("در حال یادگیری",state.learningCount,tokens.info,tokens.info.copy(alpha=.10f),Icons.Outlined.History,Modifier.weight(1f));LibraryStatCard("یادگرفته",state.learnedCount,tokens.success,tokens.success.copy(alpha=.10f),Icons.Outlined.CheckCircle,Modifier.weight(1f));LibraryStatCard("کل واژگان",state.totalCount,tokens.primary,tokens.primary.copy(alpha=.10f),Icons.Outlined.Book,Modifier.weight(1f))}
  Spacer(Modifier.height(tokens.sectionGap));Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.End){Text("فیلترها",color=tokens.primary,style=MaterialTheme.typography.titleLarge.copy(fontWeight=FontWeight.Bold));Spacer(Modifier.width(tokens.compactGap));Icon(Icons.Outlined.FilterList,"فیلترها",tint=tokens.primary)};Spacer(Modifier.height(tokens.contentGap))
  Card(Modifier.fillMaxWidth(),shape=RoundedCornerShape(tokens.libraryCategoryCorner),colors=CardDefaults.cardColors(containerColor=tokens.cardColor),border=BorderStroke(tokens.borderThin,tokens.outlineColor)){Row(Modifier.fillMaxWidth().padding(horizontal=tokens.contentPadding,vertical=tokens.contentPadding),verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(tokens.contentGap)){Surface(Modifier.size(tokens.libraryIconTileSize),shape=RoundedCornerShape(tokens.libraryIconTileCorner),color=tokens.primary.copy(alpha=.10f)){Box(contentAlignment=Alignment.Center){Icon(Icons.Outlined.Folder,"دسته‌بندی‌ها",tint=tokens.primary,modifier=Modifier.size(tokens.iconLarge))}};Column(Modifier.weight(1f),horizontalAlignment=Alignment.End){Text("دسته‌بندی‌ها",color=tokens.primary,style=MaterialTheme.typography.titleMedium.copy(fontWeight=FontWeight.Bold));Text("همه دسته‌ها • "+toFaDigits(state.categories.size)+" دسته انتخاب شده",color=tokens.onSurfaceVariant,style=MaterialTheme.typography.bodySmall)};Icon(tokens.icons.back,"انتخاب دسته",tint=tokens.primary)}}
  Spacer(Modifier.height(tokens.tinyGap));if(state.categories.isNotEmpty()){Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(tokens.microGap)){FilterChip(selected=state.selectedCategoryId==null,onClick={viewModel.onCategoryChange(null)},label={Text("همه")});state.categories.forEach{category->FilterChip(selected=state.selectedCategoryId==category.id,onClick={viewModel.onCategoryChange(category.id)},label={Text(category.name)})}};Spacer(Modifier.height(tokens.tinyGap))}
  Row(Modifier.fillMaxWidth().horizontalScroll(rememberScrollState()),horizontalArrangement=Arrangement.spacedBy(tokens.microGap)){FilterChip(selected=!state.favoritesOnly,onClick={viewModel.onFavoritesChange(false)},label={Text("همه")});FilterChip(selected=state.favoritesOnly,onClick={viewModel.onFavoritesChange(true)},label={Text("موردعلاقه‌ها")});FilterChip(selected=false,onClick={viewModel.removeExactDuplicates{count->duplicateMessage=if(count==0)"تکراری پیدا نشد." else toFaDigits(count)+" واژه تکراری Merge شد."}},enabled=!state.isDuplicateCleanupBusy,label={Text(if(state.isDuplicateCleanupBusy)"در حال Merge..." else "تکراری‌ها")})}
  Spacer(Modifier.height(tokens.compactGap));duplicateMessage?.let{Text(it,Modifier.fillMaxWidth(),textAlign=TextAlign.End,color=tokens.primary,style=MaterialTheme.typography.bodySmall)}
  when{state.isLoading->Box(Modifier.weight(1f).fillMaxWidth(),contentAlignment=Alignment.Center){CircularProgressIndicator(color=tokens.primary)};state.error!=null->Box(Modifier.weight(1f).fillMaxWidth(),contentAlignment=Alignment.Center){Text("خطا: "+state.error,color=tokens.error)};state.items.isEmpty()->Box(Modifier.weight(1f).fillMaxWidth(),contentAlignment=Alignment.Center){Text("واژه‌ای پیدا نشد.")};else->LazyColumn(Modifier.weight(1f).fillMaxWidth(),verticalArrangement=Arrangement.spacedBy(tokens.itemGap),contentPadding=PaddingValues(vertical=tokens.tinyGap)){items(state.items,key={it.concept.id}){item->VocabularyCard(item,languagePair){onOpen(item.concept.id)}}}}
 }
}
@Composable private fun LibraryStatCard(title:String,value:Int,color:Color,background:Color,icon:androidx.compose.ui.graphics.vector.ImageVector,modifier:Modifier){val tokens=LocalFlashLearnThemeTokens.current;Card(modifier=modifier.height(tokens.libraryStatHeight),shape=RoundedCornerShape(tokens.libraryCardCorner),colors=CardDefaults.cardColors(containerColor=background),border=BorderStroke(tokens.borderThin,color.copy(alpha=.14f))){Column(Modifier.fillMaxSize().padding(vertical=tokens.compactPadding,horizontal=tokens.tinyGap),horizontalAlignment=Alignment.CenterHorizontally,verticalArrangement=Arrangement.Center){Icon(icon,title,tint=color,modifier=Modifier.size(tokens.libraryStatIconSize));Spacer(Modifier.height(tokens.tinyGap));Text(title,color=color,style=MaterialTheme.typography.titleSmall.copy(fontWeight=FontWeight.Bold),textAlign=TextAlign.Center);Text(toFaDigits(value),color=color,style=MaterialTheme.typography.headlineSmall.copy(fontWeight=FontWeight.Bold))}}}
@Composable private fun VocabularyCard(item:LibraryItem,languagePair:LanguagePair,onOpen:()->Unit){val tokens=LocalFlashLearnThemeTokens.current;Card(Modifier.fillMaxWidth().clickable(onClick=onOpen),shape=RoundedCornerShape(tokens.libraryCardCorner),colors=CardDefaults.cardColors(containerColor=tokens.cardColor),border=BorderStroke(tokens.borderThin,tokens.outlineColor)){Row(Modifier.fillMaxWidth().padding(horizontal=tokens.contentGap,vertical=tokens.contentGap),verticalAlignment=Alignment.CenterVertically){Icon(Icons.Outlined.MoreVert,"گزینه‌ها",tint=tokens.onSurfaceVariant,modifier=Modifier.size(tokens.libraryWordIconSize));Spacer(Modifier.width(tokens.compactGap));DifficultyPill(item.difficulty);Spacer(Modifier.weight(1f));Column(horizontalAlignment=Alignment.End){Row(verticalAlignment=Alignment.CenterVertically){Text(item.source?.text?:"—",color=tokens.primary,style=MaterialTheme.typography.titleMedium.copy(fontWeight=FontWeight.Bold));Spacer(Modifier.width(tokens.microGap));Text(languagePair.source.flag,style=MaterialTheme.typography.titleMedium)};Spacer(Modifier.height(tokens.tinyGap));if(item.targets.isEmpty())Text("—",color=tokens.onSurfaceVariant,style=MaterialTheme.typography.bodyMedium)else item.targets.forEachIndexed{index,target->Row(verticalAlignment=Alignment.CenterVertically){Text(target.text,color=tokens.onSurfaceVariant,style=MaterialTheme.typography.bodyMedium);Spacer(Modifier.width(tokens.microGap));Text(languagePair.target.flag,style=MaterialTheme.typography.titleMedium);if(index<item.targets.lastIndex)Text("،",color=tokens.onSurfaceVariant)}};Spacer(Modifier.height(tokens.tinyGap));item.category?.let{Text(it.name,color=tokens.info,style=MaterialTheme.typography.labelSmall.copy(fontWeight=FontWeight.Bold))}};Spacer(Modifier.width(tokens.contentGap));Icon(Icons.Outlined.StarBorder,"موردعلاقه",tint=tokens.onSurfaceVariant,modifier=Modifier.size(tokens.libraryFavoriteIconSize))}}}
@Composable private fun DifficultyPill(difficulty:VocabularyDifficulty?){val tokens=LocalFlashLearnThemeTokens.current;val (label,foreground)=when(difficulty){VocabularyDifficulty.EASY,null->"آسان" to tokens.success;VocabularyDifficulty.MEDIUM->"متوسط" to tokens.warning;VocabularyDifficulty.HARD->"سخت" to tokens.error;VocabularyDifficulty.VERY_HARD->"خیلی سخت" to tokens.critical};val background=foreground.copy(alpha=.10f);Surface(shape=RoundedCornerShape(tokens.cornerMedium),color=background){Text(label,color=foreground,style=MaterialTheme.typography.labelLarge.copy(fontWeight=FontWeight.Bold),modifier=Modifier.padding(horizontal=tokens.libraryDifficultyHorizontalPadding,vertical=tokens.libraryDifficultyVerticalPadding))}}
private fun toFaDigits(value:Int):String=value.toString().map{when(it){'0'->'۰';'1'->'۱';'2'->'۲';'3'->'۳';'4'->'۴';'5'->'۵';'6'->'۶';'7'->'۷';'8'->'۸';'9'->'۹';else->it}}.joinToString("")
